$('closeOrganize').onclick=closeOrganize;$('cancelOrganize').onclick=closeOrganize;$('saveOrganize').onclick=saveOrganize;$('organizeAssetSearch').oninput=renderOrganizeAssetTree;$('organizeModal').onclick=e=>{if(e.target===$('organizeModal'))closeOrganize()};
$('externalLinkForm').addEventListener('submit',e=>{const statusBox=$('externalLinkStatus');statusBox.textContent='';statusBox.className='external-link-status';if(!$('folder').value||$('folder').value==='0'){e.preventDefault();e.stopImmediatePropagation();$('externalDetails').open=true;statusBox.textContent='Kies eerst bovenaan een concrete doelmap; “Alle mappen” is geen opslaglocatie.';statusBox.className='external-link-status error';openFolderPicker()}},true);
if($('reindex'))$('reindex').onclick=async()=>{const button=$('reindex'),box=$('indexStatus'),started=Date.now();button.disabled=true;button.textContent='Indexeren…';box.hidden=false;box.className='index-status busy';box.innerHTML='<span class="spinner" aria-hidden="true"></span><span>Zoekindex wordt in batches bijgewerkt…</span>';box.scrollIntoView({behavior:'smooth',block:'nearest'});let total=0,again=true,counts={'gereed':0,'niet-ondersteund':0,'ocr-nodig':0,'overgeslagen':0,'mislukt':0};try{while(again){const d=await call('document_api.php?action=reindex',{method:'POST'});total+=Number(d.processed||0);for(const key of Object.keys(counts))counts[key]+=Number(d.counts?.[key]||0);again=Boolean(d.remaining);button.textContent='Indexeren… '+total}const wait=Math.max(0,1200-(Date.now()-started));if(wait)await new Promise(resolve=>setTimeout(resolve,wait));const details=total?' Gereed: '+counts.gereed+', niet ondersteund: '+counts['niet-ondersteund']+', OCR nodig: '+counts['ocr-nodig']+', overgeslagen: '+counts.overgeslagen+', mislukt: '+counts.mislukt+'.':'';box.className='index-status';box.textContent=total?total+' documenten voor de zoekindex verwerkt.'+details:'De zoekindex is al volledig bijgewerkt.';box.scrollIntoView({behavior:'smooth',block:'nearest'});await load()}catch(e){box.className='index-status error';box.textContent=e.message;box.scrollIntoView({behavior:'smooth',block:'nearest'})}finally{button.disabled=false;button.textContent='Zoekindex bijwerken'}};
async function showIndexDetails(){const section=$('indexDetails');section.hidden=false;$('indexSummary').textContent='Status wordt opgehaald…';$('indexIssues').innerHTML='';try{const d=await call('document_api.php?action=index_status'),s=d.summary;$('indexSummary').textContent='Gereed: '+s.gereed+' · niet ondersteund: '+s['niet-ondersteund']+' · OCR nodig: '+s['ocr-nodig']+' · overgeslagen: '+s.overgeslagen+' · mislukt: '+s.mislukt+' · nog niet geïndexeerd: '+s['niet-geindexeerd'];$('indexIssues').innerHTML=d.issues.length?d.issues.map(x=>'<div class="index-issue"><strong>'+esc(x.OrigineleNaam)+'</strong><span>'+esc(x.MapNaam)+'</span><span class="state">'+esc(x.Status)+'</span><span class="reason">'+esc(x.Reden)+'</span>'+(x.OpnieuwProberen?'<button type="button" class="btn" onclick="retryIndex('+x.DocumentID+')">Opnieuw proberen</button>':'<span></span>')+'</div>').join(''):'<p>Er zijn geen documenten die aandacht nodig hebben.</p>'}catch(e){$('indexSummary').textContent=e.message}};
async function retryIndex(id){try{const d=await call('document_api.php?action=reindex_one&id='+id,{method:'POST'});msg('Document opnieuw verwerkt. Nieuwe indexstatus: '+d.status+'.');await showIndexDetails()}catch(e){msg(e.message,true)}}
if($('indexDetailsButton'))$('indexDetailsButton').onclick=showIndexDetails;if($('closeIndexDetails'))$('closeIndexDetails').onclick=()=>$('indexDetails').hidden=true;
['dragenter','dragover'].forEach(type=>$('dropZone').addEventListener(type,e=>{e.preventDefault();e.stopPropagation();$('dropZone').classList.add('dragover')}));['dragleave','drop'].forEach(type=>$('dropZone').addEventListener(type,e=>{e.preventDefault();e.stopPropagation();$('dropZone').classList.remove('dragover')}));$('dropZone').addEventListener('drop',async e=>{try{chooseFiles(await droppedFiles(e.dataTransfer))}catch(error){status('De gesleepte map kon niet worden gelezen: '+error.message,'error')}});
$('externalLinkForm').onsubmit=async e=>{e.preventDefault();if(!$('folder').value||$('folder').value==='0'){msg('Kies eerst bovenaan de map waarin de videolink moet worden opgeslagen.',true);openFolderPicker();return}const button=e.submitter,data=new FormData();data.append('title',$('linkTitle').value.trim());data.append('url',$('linkUrl').value.trim());data.append('tags',$('linkTags').value.trim());data.append('description',$('linkDescription').value.trim());button.disabled=true;try{await call('document_api.php?action=add_link&map='+encodeURIComponent($('folder').value),{method:'POST',body:data});e.target.reset();msg('Externe videolink veilig opgeslagen.');await load()}catch(error){msg(error.message,true)}finally{button.disabled=false}};
$('upload').onsubmit=async e=>{e.preventDefault();if(!$('folder').value||$('folder').value==='0'){const warning='Kies eerst bovenaan de map waarin de bestanden of gekozen map moeten worden opgeslagen.';status(warning,'error');msg(warning,true);openFolderPicker();return}if(!selectedFiles.length){openPicker();return}const button=$('uploadButton'),failures=[],total=selectedFiles.length;let success=0;button.disabled=true;msg('');progressStart(total);for(let i=0;i<total;i++){const item=selectedFiles[i],file=item.file;progressUpdate(i,total,'Bezig: '+item.relativePath);status('Bezig met '+(i+1)+' van '+total+': '+item.relativePath);const data=new FormData();data.append('file',file,file.name);data.append('relativePath',item.relativePath);data.append('tags',$('tags').value);if(total===1&&$('title').value.trim())data.append('title',$('title').value.trim());try{await call('document_api.php?action=upload&map='+encodeURIComponent($('folder').value),{method:'POST',body:data});success++}catch(error){failures.push(item.relativePath+': '+error.message)}progressUpdate(i+1,total,item.relativePath)}button.disabled=false;progressStop();if(success){await folders($('folder').value);await load()}if(!failures.length){e.target.reset();selectedFiles=[];status(success+' bestand'+(success===1?'':'en')+' veilig opgeslagen; mappenstructuur behouden.','success');msg(success+' bestand'+(success===1?' is':'en zijn')+' veilig opgeslagen.')}else{status('Voltooid: '+success+' opgeslagen, '+failures.length+' mislukt.\n'+failures.join('\n'),'error');msg(success+' opgeslagen; '+failures.length+' mislukt. Bekijk de rode melding onder het sleepvlak.',true)}};
function updateViewButton(){$('viewToggle').textContent=viewMode==='tiles'?'Lijstweergave':'Tegelweergave';$('viewToggle').setAttribute('aria-pressed',viewMode==='list'?'true':'false')}
(async()=>{updateViewButton();await folders(initialMap);await load()})();
</script>
</body>
</html>
